function (e) {
        e.preventDefault();
        var run = map[provider];
        var runOpts = {
          referral_code: affiliateCodeForSocial(opts.referral_code),
          remember_me: opts.remember_me
        };
        if (opts.onStart) opts.onStart(provider);
        if (provider === 'google' && googleActivatorReady) {
          startGoogleLoginFromUserGesture(runOpts)
            .then(function (user) {
              if (opts.onSuccess) opts.onSuccess(provider, user);
            })
            .catch(function (err) {
              if (opts.onError) opts.onError(provider, err);
            });
          return;
        }
        run(runOpts)
          .then(function (user) {
            if (opts.onSuccess) opts.onSuccess(provider, user);
          })
          .catch(function (err) {
            if (opts.onError) opts.onError(provider, err);
          });
      }
